import re, pathlib

def test_probe():
    root = pathlib.Path(__file__).resolve().parent.parent
    bad = []
    for base in ('src', 'tests', 'docs'):
        for p in (root / base).rglob('*'):
            if p.suffix in ('.py', '.rst', '.md') and p.name != 'test_probe_review.py':
                for i, l in enumerate(p.read_text(errors='ignore').splitlines(), 1):
                    if re.search(r'(?<![A-Za-z_])Styles\b', l):
                        bad.append(f'{p}:{i}:{l}')
    assert not bad, bad

