import pytest
import attr
from attr import setters


@pytest.mark.parametrize('nop', [None, setters.NO_OP])
@pytest.mark.parametrize('slots', [True, False])
def test_frozen_nop_works(nop, slots):
    @attr.s(frozen=True, slots=slots)
    class C:
        x = attr.ib(on_setattr=nop)

    c = C(1)
    assert c.x == 1
    with pytest.raises(attr.exceptions.FrozenInstanceError):
        c.x = 2


def test_frozen_real_setter_still_raises():
    with pytest.raises(ValueError) as ei:
        @attr.s(frozen=True)
        class D:
            x = attr.ib(on_setattr=setters.validate)
    assert ei.value.args[0] == "Frozen classes can't use on_setattr."


def test_frozen_nop_hash_cache():
    @attr.s(frozen=True, cache_hash=True, hash=True)
    class E:
        x = attr.ib(on_setattr=setters.NO_OP)

    assert hash(E(1)) == hash(E(1))

