@pytest.mark.parametrize('nop', [None, setters.NO_OP])
@pytest.mark.parametrize('slots', [True, False])
def test_make_init_script_frozen_nop(monkeypatch, nop, slots):
    calls = []
    orig = m._make_init_script

    def spy(*a, **k):
        calls.append(1)
        return orig(*a, **k)

    monkeypatch.setattr(m, '_make_init_script', spy)

    @attr.s(frozen=True, slots=slots)
    class C:
        x = attr.ib(on_setattr=nop)
        y = attr.ib(default=3)

    assert calls
    c = C(1)
    assert (c.x, c.y) == (1, 3)
    with pytest.raises(attr.exceptions.FrozenInstanceError):
        c.x = 2


def test_make_init_script_frozen_real_setter_raises(monkeypatch):
    calls = []
    orig = m._make_init_script

    def spy(*a, **k):
        calls.append(1)
        return orig(*a, **k)

    monkeypatch.setattr(m, '_make_init_script', spy)
