import pytest
from pydantic import BaseModel, Field, RootModel
from pydantic._internal._discriminated_union import _ApplyInferredDiscriminator


def test_none_disc():
    class A(BaseModel):
        f: Literal['A'] = 'A'

    class B(BaseModel):
        f: None = None

    class M(BaseModel):
        x: Union[A, B] = Field(discriminator='f')

    assert isinstance(M.model_validate({'x': {'f': None}}).x, B)
    assert isinstance(M.model_validate({'x': {'f': 'A'}}).x, A)
    assert M.model_json_schema()['properties']['x']['discriminator']['mapping'] == {'A': '#/$defs/A', 'null': '#/$defs/B'}


def test_root_model_and_union_disc():
    class R(RootModel[Literal['r']]):
        pass

    class A(BaseModel):
        f: R

    class B(BaseModel):
        f: Union[Literal['b1'], Literal['b2']]

    class M(BaseModel):
        x: Union[A, B] = Field(discriminator='f')

    assert isinstance(M.model_validate({'x': {'f': 'r'}}).x, A)
    assert isinstance(M.model_validate({'x': {'f': 'b2'}}).x, B)

